-- --- Helpers (security definer, fixed search_path) -----------------------------

create or replace function taxiflow_private.is_active_member(p_business_id uuid, p_roles text[] default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.business_memberships m
    where m.business_id = p_business_id
      and m.user_id = auth.uid()
      and m.active
      and (p_roles is null or m.role = any (p_roles))
  );
$$;

create or replace function taxiflow_private.forbid_tenant_reassignment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Separate branches: PL/pgSQL resolves every NEW field named in an
  -- expression, so a combined condition naming new.user_id breaks every
  -- workspace_snapshots update (that table has no user_id).
  if tg_table_name = 'workspace_snapshots' then
    if new.business_id is distinct from old.business_id then
      raise exception 'A workspace snapshot cannot be moved to another business.' using errcode = '42501';
    end if;
  elsif tg_table_name = 'business_memberships' then
    if new.business_id is distinct from old.business_id or new.user_id is distinct from old.user_id then
      raise exception 'A membership cannot be moved to another business or user.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists workspace_snapshots_no_tenant_reassignment on public.workspace_snapshots;
create trigger workspace_snapshots_no_tenant_reassignment
  before update on public.workspace_snapshots
  for each row execute function taxiflow_private.forbid_tenant_reassignment();

drop trigger if exists business_memberships_no_reassignment on public.business_memberships;
create trigger business_memberships_no_reassignment
  before update on public.business_memberships
  for each row execute function taxiflow_private.forbid_tenant_reassignment();

-- === Hosted access section (replaces the local grants/RLS section) =============

-- Every policy on workspace_snapshots (live: "Authenticated users can
-- read/insert/update workspace snapshots"), whatever it is called.
do $$
declare p record;
begin
  for p in select policyname from pg_policies where schemaname = 'public' and tablename = 'workspace_snapshots' loop
    execute format('drop policy %I on public.workspace_snapshots', p.policyname);
  end loop;
end $$;

-- Every privilege anon, authenticated and PUBLIC hold on any public relation
-- (tables, views, sequences), then RLS on every public table.
do $$
declare r record;
begin
  for r in
    select c.relname, c.relkind from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'S', 'f')
  loop
    if r.relkind = 'S' then
      execute format('revoke all on sequence public.%I from anon, authenticated, public', r.relname);
    else
      execute format('revoke all on table public.%I from anon, authenticated, public', r.relname);
    end if;
    if r.relkind in ('r', 'p') then
      execute format('alter table public.%I enable row level security', r.relname);
    end if;
  end loop;
end $$;

-- The legacy view must not run with its owner's rights.
alter view if exists public.compliance_dashboard set (security_invoker = true);

-- Every public function: no execute for anon, authenticated or PUBLIC (live has
-- none today; this also covers anything added since the inventory).
do $$
declare f record;
begin
  for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' loop
    execute format('revoke all on function %s from anon, authenticated, public', f.sig);
  end loop;
end $$;

-- Live default privileges hand anon/authenticated everything on new objects
-- created by postgres in public. Remove them. (TaxiFlow never creates objects
-- as supabase_admin; explicit revokes in every migration still apply.)
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated, public;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated, public;
alter default privileges for role postgres in schema public revoke all on functions from anon, authenticated, public;

-- The only browser access the tenant model needs: read your own memberships and
-- businesses (RLS limits the rows). Everything else goes through the server.
grant select on table public.businesses to authenticated;
grant select on table public.business_memberships to authenticated;

revoke all on function taxiflow_private.is_active_member(uuid, text[]) from public, anon, authenticated, service_role;
revoke all on function taxiflow_private.forbid_tenant_reassignment() from public, anon, authenticated;
grant usage on schema taxiflow_private to authenticated;
grant execute on function taxiflow_private.is_active_member(uuid, text[]) to authenticated;

drop policy if exists "members read their businesses" on public.businesses;
create policy "members read their businesses" on public.businesses
  for select to authenticated
  using (taxiflow_private.is_active_member(id));

drop policy if exists "read own or administered memberships" on public.business_memberships;
create policy "read own or administered memberships" on public.business_memberships
  for select to authenticated
  using (
    (user_id = auth.uid() and active)
    or taxiflow_private.is_active_member(business_id, array['Owner', 'Admin'])
  );

-- --- Assertions (any failure aborts and rolls back this migration) ----------------
do $$
declare
  leftover text;
begin
  select string_agg(policyname, ', ') into leftover
  from pg_policies where schemaname = 'public' and tablename = 'workspace_snapshots';
  if leftover is not null then raise exception 'Policies remain on workspace_snapshots: %', leftover; end if;

  select string_agg(table_name || ':' || grantee || ':' || privilege_type, ', ' order by table_name, grantee, privilege_type) into leftover
  from information_schema.role_table_grants
  where table_schema = 'public'
    and (grantee in ('anon', 'PUBLIC')
         or (grantee = 'authenticated' and not (table_name in ('businesses', 'business_memberships') and privilege_type = 'SELECT')));
  if leftover is not null then raise exception 'Browser grants remain: %', leftover; end if;

  select string_agg(c.relname, ', ') into leftover
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity;
  if leftover is not null then raise exception 'Tables without RLS: %', leftover; end if;

  select string_agg(p.oid::regprocedure::text, ', ') into leftover
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
  if leftover is not null then raise exception 'Browser-executable public functions: %', leftover; end if;
-- [Preview test schema] removed: legacy-workspace Owner assertion (no legacy workspace in a fresh project).
end $$;


-- ===== 02 finance actions (scripts/localdb/migrations/20261010063144_finance_actions.sql, unchanged) =====
-- Scoped server writes for finance/cash-up actions (LOCAL; never applied to a
-- hosted project from here). Idempotency log + one atomic commit function that
-- the server calls with the service role AFTER tenant authorization.

create table if not exists public.finance_action_requests (
  business_id uuid not null references public.businesses (id) on delete restrict,
  request_id uuid not null,
  user_id uuid not null references auth.users (id),
  action text not null,
  target_id text not null,
  request_hash text not null,
  response jsonb not null,
  created_at timestamptz not null default now(),
  primary key (business_id, request_id)
);

alter table public.finance_action_requests enable row level security;
revoke all on table public.finance_action_requests from public, anon, authenticated;

-- One transaction: replay check, compare-and-swap on updated_at, request log.
-- A stale p_expected_updated_at changes nothing and returns 'conflict'.
create or replace function public.commit_finance_action(
  p_business_id uuid,
  p_expected_updated_at timestamptz,
  p_snapshot jsonb,
  p_updated_by uuid,
  p_request_id uuid,
  p_action text,
  p_target_id text,
  p_request_hash text,
  p_response jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing public.finance_action_requests;
  v_version timestamptz := clock_timestamp();
  v_rows integer;
begin
  select * into v_existing from public.finance_action_requests
  where business_id = p_business_id and request_id = p_request_id;
  if found then
    if v_existing.request_hash <> p_request_hash or v_existing.user_id <> p_updated_by then
      return jsonb_build_object('status', 'request_id_reused');
    end if;
    return jsonb_build_object('status', 'replayed', 'response', v_existing.response);
  end if;

  update public.workspace_snapshots
  set snapshot = p_snapshot, updated_at = v_version, updated_by = p_updated_by
  where business_id = p_business_id and updated_at = p_expected_updated_at;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    return jsonb_build_object('status', 'conflict');
  end if;

  insert into public.finance_action_requests (business_id, request_id, user_id, action, target_id, request_hash, response)
  values (p_business_id, p_request_id, p_updated_by, p_action, p_target_id, p_request_hash,
          p_response || jsonb_build_object('version', v_version));

  return jsonb_build_object('status', 'applied', 'version', v_version, 'response', p_response || jsonb_build_object('version', v_version));
end;
$$;

revoke all on function public.commit_finance_action(uuid, timestamptz, jsonb, uuid, uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.commit_finance_action(uuid, timestamptz, jsonb, uuid, uuid, text, text, text, jsonb) to service_role;


-- ===== 03 pilot onboarding (scripts/localdb/migrations/20261010113000_pilot_onboarding.sql, unchanged) =====
-- Pilot onboarding (LOCAL hardened variant; never applied to a hosted project
-- from here). Design: project-os/04-technical/tenant-design.md (Task 18).
-- Idempotent.
--
-- 1. A business always keeps at least one active Owner (database guard, so no
--    code path can remove the last one).
-- 2. Business creation with its initial Owner is an operator-only RPC
--    (service_role). Public users cannot create businesses or appoint Owners.
-- 3. Membership changes go through ONE server path (POST /api/business/members)
--    that calls a service_role-only RPC: the membership and the business
--    directory entry change in one transaction, with a snapshot compare-and-swap.
--    The earlier browser-callable set_business_membership is withdrawn.

-- --- 1. Last active Owner guard --------------------------------------------------
create or replace function taxiflow_private.keep_an_active_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  remaining integer;
begin
  if not (old.role = 'Owner' and old.active) then
    return coalesce(new, old);
  end if;
  if tg_op = 'UPDATE' and new.role = 'Owner' and new.active then
    return new;
  end if;
  -- Serialize concurrent changes to the same business's Owners.
  perform 1 from public.businesses where id = old.business_id for update;
  select count(*) into remaining
  from public.business_memberships
  where business_id = old.business_id
    and role = 'Owner'
    and active
    and user_id <> old.user_id;
  if remaining = 0 then
    raise exception 'A business must keep at least one active Owner.' using errcode = '42501';
  end if;
  return coalesce(new, old);
end;
$$;

drop trigger if exists business_memberships_keep_owner on public.business_memberships;
create trigger business_memberships_keep_owner
  before update or delete on public.business_memberships
  for each row execute function taxiflow_private.keep_an_active_owner();

-- --- 2. Operator: create a business with its initial Owner ----------------------
-- Idempotent by slug: a retry with the same slug and Owner returns 'existing'.
create or replace function public.create_business_with_owner(
  p_slug text,
  p_name text,
  p_owner_user_id uuid,
  p_owner_driver_staff_id text,
  p_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_business public.businesses;
  v_owner public.business_memberships;
begin
  select * into v_business from public.businesses where slug = p_slug;
  if found then
    select * into v_owner from public.business_memberships
    where business_id = v_business.id and user_id = p_owner_user_id and role = 'Owner';
    if not found then
      return jsonb_build_object('status', 'slug_taken');
    end if;
    return jsonb_build_object('status', 'existing', 'business_id', v_business.id, 'owner_active', v_owner.active);
  end if;

  insert into public.businesses (slug, name) values (p_slug, p_name) returning * into v_business;
  insert into public.workspace_snapshots (workspace_key, snapshot, updated_at, updated_by, business_id)
  values (p_slug, p_snapshot, clock_timestamp(), p_owner_user_id, v_business.id);
  insert into public.business_memberships (business_id, user_id, role, driver_staff_id, active, updated_by)
  values (v_business.id, p_owner_user_id, 'Owner', nullif(trim(p_owner_driver_staff_id), ''), true, p_owner_user_id);
  return jsonb_build_object('status', 'created', 'business_id', v_business.id);
end;
$$;

-- --- 3. Owner-managed membership change (called by the server only) -------------
-- p_actor is the server-verified caller. Rules (also checked by the server):
--   * the actor is an active Owner of p_business_id;
--   * Owners are never created or changed here, except an Owner's OWN driver link;
--   * no change to one's own role or active flag;
--   * roles assignable here: Admin, Manager, Driver;
--   * the membership row and the business directory snapshot commit together,
--     and only if the snapshot is still at p_expected_updated_at.
create or replace function public.apply_membership_change(
  p_business_id uuid,
  p_actor uuid,
  p_user_id uuid,
  p_role text,
  p_active boolean,
  p_driver_staff_id text,
  p_expected_updated_at timestamptz,
  p_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor public.business_memberships;
  v_existing public.business_memberships;
  v_version timestamptz := clock_timestamp();
  v_rows integer;
begin
  select * into v_actor from public.business_memberships
  where business_id = p_business_id and user_id = p_actor and active and role = 'Owner';
  if not found then
    raise exception 'Only an active Owner of this business can manage its access.' using errcode = '42501';
  end if;

  select * into v_existing from public.business_memberships
  where business_id = p_business_id and user_id = p_user_id;

  if p_user_id = p_actor then
    if p_role is distinct from 'Owner' or p_active is distinct from true then
      raise exception 'You cannot change your own role or access.' using errcode = '42501';
    end if;
  else
    if p_role is null or p_role not in ('Admin', 'Manager', 'Driver') then
      raise exception 'Role % cannot be assigned here.', coalesce(p_role, 'null') using errcode = '42501';
    end if;
    if found and v_existing.role = 'Owner' then
      raise exception 'Owner access is managed by the operator.' using errcode = '42501';
    end if;
  end if;

  if p_snapshot is not null then
    update public.workspace_snapshots
    set snapshot = p_snapshot, updated_at = v_version, updated_by = p_actor
    where business_id = p_business_id and updated_at = p_expected_updated_at;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      return jsonb_build_object('status', 'conflict');
    end if;
  end if;

  insert into public.business_memberships (business_id, user_id, role, driver_staff_id, active, updated_by)
  values (p_business_id, p_user_id, p_role, nullif(trim(p_driver_staff_id), ''), p_active, p_actor)
  on conflict (business_id, user_id) do update
    set role = excluded.role,
        driver_staff_id = excluded.driver_staff_id,
        active = excluded.active,
        updated_at = now(),
        updated_by = excluded.updated_by;

  return jsonb_build_object('status', 'applied', 'version', v_version);
end;
$$;

-- --- Grants -------------------------------------------------------------------------
revoke all on function taxiflow_private.keep_an_active_owner() from public, anon, authenticated;
revoke all on function public.create_business_with_owner(text, text, uuid, text, jsonb) from public, anon, authenticated;
grant execute on function public.create_business_with_owner(text, text, uuid, text, jsonb) to service_role;
revoke all on function public.apply_membership_change(uuid, uuid, uuid, text, boolean, text, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.apply_membership_change(uuid, uuid, uuid, text, boolean, text, timestamptz, jsonb) to service_role;
-- One membership path: the browser RPC from the local foundation is withdrawn.
-- (The hosted foundation never creates it, so this is conditional.)
do $$ begin
  if to_regprocedure('public.set_business_membership(uuid, uuid, text, boolean, text)') is not null then
    revoke all on function public.set_business_membership(uuid, uuid, text, boolean, text) from public, anon, authenticated, service_role;
  end if;
end $$;


-- ===== 04 assign initial owner (scripts/localdb/migrations/20261011090000_assign_initial_owner.sql, unchanged) =====
-- Operator: assign the INITIAL Owner of an EXISTING business (e.g. the mapped
-- legacy workspace when the directory backfill produced no active Owner).
-- Deployable unchanged (hosted release file 04). Idempotent. service_role only.
--
-- Refuses when the business already has an active Owner: replacing or adding
-- Owners of a running business is not an operator shortcut. The membership and
-- the business directory entry change in one transaction, and the directory
-- write only applies if the snapshot is still at p_expected_updated_at.
create or replace function public.assign_initial_owner(
  p_business_id uuid,
  p_user_id uuid,
  p_driver_staff_id text,
  p_expected_updated_at timestamptz,
  p_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing public.business_memberships;
  v_version timestamptz := clock_timestamp();
  v_rows integer;
begin
  if not exists (select 1 from public.businesses where id = p_business_id) then
    return jsonb_build_object('status', 'no_business');
  end if;
  -- Serialize with other Owner changes for this business.
  perform 1 from public.businesses where id = p_business_id for update;

  select * into v_existing from public.business_memberships
  where business_id = p_business_id and user_id = p_user_id;
  if found and v_existing.role = 'Owner' and v_existing.active then
    return jsonb_build_object('status', 'already_owner');
  end if;
  if exists (
    select 1 from public.business_memberships
    where business_id = p_business_id and role = 'Owner' and active
  ) then
    return jsonb_build_object('status', 'has_owner');
  end if;

  if p_snapshot is not null then
    update public.workspace_snapshots
    set snapshot = p_snapshot, updated_at = v_version, updated_by = p_user_id
    where business_id = p_business_id and updated_at = p_expected_updated_at;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      return jsonb_build_object('status', 'conflict');
    end if;
  end if;

  insert into public.business_memberships (business_id, user_id, role, driver_staff_id, active, updated_by)
  values (p_business_id, p_user_id, 'Owner', nullif(trim(p_driver_staff_id), ''), true, p_user_id)
  on conflict (business_id, user_id) do update
    set role = 'Owner',
        driver_staff_id = coalesce(excluded.driver_staff_id, public.business_memberships.driver_staff_id),
        active = true,
        updated_at = now(),
        updated_by = excluded.updated_by;

  return jsonb_build_object('status', 'assigned', 'version', v_version);
end;
$$;

revoke all on function public.assign_initial_owner(uuid, uuid, text, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.assign_initial_owner(uuid, uuid, text, timestamptz, jsonb) to service_role;


-- ===== 05 platform admins (scripts/localdb/migrations/20261018090000_platform_admins.sql, unchanged) =====
-- Platform administration (hosted release file 05). Deployable unchanged.
--
-- A platform admin may create companies (businesses) and onboard each company's
-- initial Owner through the app. It is an EXPLICIT grant, separate from business
-- memberships:
-- * it grants NO access to any company's data (workspace snapshots, members,
--   reports, finance): that still needs an active business membership;
-- * rows are written only by the operator (postgres); there is no browser,
--   API or service-role write path, so nobody can grant it to themselves;
-- * the server reads it with the service role only after validating the
--   caller's access token, and only for the caller's own user id.
-- Idempotent.
create table if not exists public.platform_admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  active boolean not null default true,
  granted_at timestamptz not null default now(),
  granted_by text not null default 'operator',
  note text
);

alter table public.platform_admins enable row level security;
alter table public.platform_admins force row level security;

-- No browser access of any kind (RLS does not govern TRUNCATE/REFERENCES/TRIGGER).
revoke all on table public.platform_admins from public, anon, authenticated;
-- The server only needs to read the caller's own row; writes stay with the operator.
revoke all on table public.platform_admins from service_role;
grant select on table public.platform_admins to service_role;
-- No policies: browser roles have no grants, and the service role bypasses RLS.
drop policy if exists "server reads platform admins" on public.platform_admins;


-- ===== 06 member permissions (scripts/localdb/migrations/20261019090000_member_permissions.sql, unchanged) =====
-- Release file 06: per-member responsibilities (additive).
--
-- Owner-assigned responsibilities on each Admin or Manager membership:
--   cash.count      record a driver's day hand-in / count standalone income
--   cash.verify     verify a counted day / standalone income
--   cash.bank       finish a deposit (bank the verified batch)
--   drivers.manage  driver profiles and driver assignments (never sign-ins)
--   fleet.manage    routes and vehicles
--   staff.manage    change other Admins'/Managers' responsibilities, only
--                   within the actor's own (never staff.manage itself, never
--                   roles or sign-ins); granted by the Owner only
-- The Owner always holds every responsibility (enforced in the server, not
-- stored). Drivers hold none. Module view access (Money, Fleet, Drivers) still
-- applies on top: a permission never bypasses a switched-off module.
--
-- Effective permissions are preserved: every existing membership is backfilled
-- with exactly what its role could do before this file (Admin counts; Manager
-- verifies and banks). A role change resets the permissions to the new role's
-- defaults, so granting a different role never carries old powers across.
-- Changes go through public.set_member_permissions (service role only): an
-- active Owner, or an active Admin/Manager holding staff.manage within its
-- delegation limits. Nobody changes their own entry or an Owner's. Every change
-- is recorded in public.member_permission_changes (one row per change, keyed by
-- business; no browser access).

create or replace function taxiflow_private.default_member_permissions(p_role text)
returns text[]
language sql
immutable
set search_path = ''
as $$
  select case p_role
    when 'Admin' then array['cash.count']::text[]
    when 'Manager' then array['cash.verify', 'cash.bank']::text[]
    else '{}'::text[]
  end;
$$;

-- Add and backfill ONLY when the column is new: existing rows get exactly their
-- role's current powers. A re-run never touches stored lists again (an Owner
-- may have emptied one on purpose).
do $$ begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'business_memberships' and column_name = 'permissions'
  ) then
    alter table public.business_memberships add column permissions text[] not null default '{}'::text[];
    update public.business_memberships
    set permissions = taxiflow_private.default_member_permissions(role)
    where taxiflow_private.default_member_permissions(role) <> '{}'::text[];
  end if;
end $$;

do $$ begin
  -- Re-created so a re-run always carries the current list of known keys.
  alter table public.business_memberships drop constraint if exists business_memberships_permissions_known;
  alter table public.business_memberships
    add constraint business_memberships_permissions_known
    check (permissions <@ array['cash.count', 'cash.verify', 'cash.bank', 'drivers.manage', 'fleet.manage', 'staff.manage']::text[]);
  if not exists (select 1 from pg_constraint where conname = 'business_memberships_permissions_roles') then
    alter table public.business_memberships
      add constraint business_memberships_permissions_roles
      check (role in ('Admin', 'Manager') or permissions = '{}'::text[]);
  end if;
end $$;

-- New memberships start with their role's defaults; a role change resets them.
create or replace function taxiflow_private.member_permissions_follow_role()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    -- Only a row that does not state its permissions (NULL: the column has no
    -- default) gets the role defaults. An explicit list, including an empty one
    -- the Owner chose, is kept exactly (a backup restore must not re-grant).
    if new.permissions is null then
      new.permissions := taxiflow_private.default_member_permissions(new.role);
    end if;
  elsif new.role is distinct from old.role then
    new.permissions := taxiflow_private.default_member_permissions(new.role);
  end if;
  return new;
end;
$$;

drop trigger if exists business_memberships_permissions_follow_role on public.business_memberships;
create trigger business_memberships_permissions_follow_role
  before insert or update on public.business_memberships
  for each row
  execute function taxiflow_private.member_permissions_follow_role();

-- After the backfill: no column default, so an insert that omits permissions
-- arrives as NULL and the trigger fills the role defaults (NOT NULL is checked
-- after BEFORE triggers); an insert that states them, e.g. a restore, is kept.
alter table public.business_memberships alter column permissions drop default;

-- Tenant-scoped audit of every responsibility change (kept on rollback).
create table if not exists public.member_permission_changes (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  actor_user_id uuid not null,
  actor_role text not null,
  target_user_id uuid not null,
  permissions_before text[] not null,
  permissions_after text[] not null,
  changed_at timestamptz not null default now()
);
create index if not exists member_permission_changes_business_idx
  on public.member_permission_changes (business_id, changed_at desc);
alter table public.member_permission_changes enable row level security;
alter table public.member_permission_changes force row level security;
revoke all on table public.member_permission_changes from public, anon, authenticated;
grant select on table public.member_permission_changes to service_role;

create or replace function public.set_member_permissions(
  p_business_id uuid,
  p_actor uuid,
  p_user_id uuid,
  p_permissions text[],
  p_expected_updated_at timestamptz,
  p_snapshot jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor public.business_memberships;
  v_target public.business_memberships;
  v_clean text[];
  v_changed text[];
  v_delegable text[];
  v_version timestamptz := clock_timestamp();
  v_rows integer;
begin
  select * into v_actor from public.business_memberships
  where business_id = p_business_id and user_id = p_actor and active;
  if not found or not (v_actor.role = 'Owner' or (v_actor.role in ('Admin', 'Manager') and 'staff.manage' = any (v_actor.permissions))) then
    raise exception 'Only the Owner, or someone given "Manage staff responsibilities", can change staff responsibilities.' using errcode = '42501';
  end if;
  if p_user_id = p_actor then
    raise exception 'You cannot change your own responsibilities.' using errcode = '42501';
  end if;

  select * into v_target from public.business_memberships
  where business_id = p_business_id and user_id = p_user_id
  for update;
  if not found then
    raise exception 'That person is not a member of this business.' using errcode = 'P0002';
  end if;
  if v_target.role not in ('Admin', 'Manager') then
    raise exception 'Only Admin and Manager responsibilities can be changed.' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct p order by p), '{}'::text[]) into v_clean
  from unnest(coalesce(p_permissions, '{}'::text[])) as p;
  if not (v_clean <@ array['cash.count', 'cash.verify', 'cash.bank', 'drivers.manage', 'fleet.manage', 'staff.manage']::text[]) then
    raise exception 'Unknown responsibility.' using errcode = '22023';
  end if;

  -- Delegation limits: a non-Owner changes only responsibilities it holds
  -- itself, never staff.manage, and never another staff manager.
  if v_actor.role <> 'Owner' then
    if 'staff.manage' = any (v_target.permissions) then
      raise exception 'Only the Owner can change the responsibilities of someone who manages staff.' using errcode = '42501';
    end if;
    select coalesce(array_agg(p), '{}'::text[]) into v_changed from (
      (select unnest(v_clean) except select unnest(v_target.permissions))
      union
      (select unnest(v_target.permissions) except select unnest(v_clean))
    ) d(p);
    v_delegable := array_remove(v_actor.permissions, 'staff.manage');
    if not (v_changed <@ v_delegable) then
      raise exception 'You can only give or remove responsibilities you hold yourself.' using errcode = '42501';
    end if;
  end if;

  if p_snapshot is not null then
    update public.workspace_snapshots
    set snapshot = p_snapshot, updated_at = v_version, updated_by = p_actor
    where business_id = p_business_id and updated_at = p_expected_updated_at;
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
      return jsonb_build_object('status', 'conflict');
    end if;
  end if;

  update public.business_memberships
  set permissions = v_clean, updated_at = now(), updated_by = p_actor
  where business_id = p_business_id and user_id = p_user_id;

  insert into public.member_permission_changes (business_id, actor_user_id, actor_role, target_user_id, permissions_before, permissions_after)
  values (p_business_id, p_actor, v_actor.role, p_user_id, v_target.permissions, v_clean);

  return jsonb_build_object(
    'status', 'applied',
    'version', case when p_snapshot is null then null else v_version end,
    'permissions', to_jsonb(v_clean)
  );
end;
$$;

revoke all on function taxiflow_private.default_member_permissions(text) from public, anon, authenticated;
revoke all on function taxiflow_private.member_permissions_follow_role() from public, anon, authenticated;
revoke all on function public.set_member_permissions(uuid, uuid, uuid, text[], timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.set_member_permissions(uuid, uuid, uuid, text[], timestamptz, jsonb) to service_role;


-- ===== 07 logbook import (scripts/localdb/migrations/20261110090000_logbook_pipeline.sql, unchanged) =====
-- Paper logbook import: review queue, audit log and automation keys (LOCAL;
-- never applied to a hosted project from here). Nothing in these tables is live
-- business data: a row reaches workspace_snapshots only through
-- commit_logbook_approval, after an Owner/Admin approved it on the server.
-- No browser access at all: every read and write goes through the server with
-- the service role, after tenant authorization, pinned to one business.

create table if not exists public.logbook_api_keys (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete restrict,
  name text not null,
  key_prefix text not null,
  key_hash text not null unique,
  scope text not null default 'logbook.import' check (scope = 'logbook.import'),
  created_by uuid not null references auth.users (id),
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  revoked_by uuid references auth.users (id),
  last_used_at timestamptz
);

create table if not exists public.logbook_api_key_usage (
  key_id uuid not null references public.logbook_api_keys (id) on delete cascade,
  window_start timestamptz not null,
  request_count integer not null default 0,
  primary key (key_id, window_start)
);

create table if not exists public.logbook_batches (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete restrict,
  source text not null check (source in ('upload', 'api')),
  model text,
  reference text,
  created_by uuid references auth.users (id),
  api_key_id uuid references public.logbook_api_keys (id),
  created_at timestamptz not null default now(),
  check ((source = 'upload' and created_by is not null) or (source = 'api' and api_key_id is not null))
);

create table if not exists public.logbook_pages (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete restrict,
  batch_id uuid not null references public.logbook_batches (id) on delete restrict,
  page_number integer not null,
  filename text,
  media_type text not null check (media_type in ('image/jpeg', 'image/png')),
  byte_size integer not null,
  sha256 text not null,
  image_base64 text not null,
  page_note text,
  created_at timestamptz not null default now(),
  -- The same photo is stored once per business; a re-upload returns the first batch.
  unique (business_id, sha256)
);

create table if not exists public.logbook_rows (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete restrict,
  batch_id uuid not null references public.logbook_batches (id) on delete restrict,
  page_id uuid references public.logbook_pages (id) on delete restrict,
  row_index integer not null,
  fields jsonb not null,
  issues jsonb not null default '[]'::jsonb,
  row_hash text not null,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  edited_by uuid references auth.users (id),
  edited_at timestamptz,
  reviewed_by uuid references auth.users (id),
  reviewed_at timestamptz,
  reject_reason text,
  live_record_ids jsonb,
  created_at timestamptz not null default now()
);

-- Duplicate guard: one pending-or-approved row per business and row hash
-- (driver + vehicle + date + amounts). A rejected row does not block a re-import.
create unique index if not exists logbook_rows_active_hash
  on public.logbook_rows (business_id, row_hash) where status <> 'rejected';
create index if not exists logbook_rows_batch on public.logbook_rows (business_id, batch_id, row_index);

-- Who extracted, imported, edited, approved or rejected each row. Append-only.
create table if not exists public.logbook_row_events (
  id bigint generated always as identity primary key,
  business_id uuid not null references public.businesses (id) on delete restrict,
  batch_id uuid not null references public.logbook_batches (id) on delete restrict,
  row_id uuid not null references public.logbook_rows (id) on delete restrict,
  action text not null check (action in ('extracted', 'imported', 'edited', 'approved', 'rejected')),
  actor_user_id uuid references auth.users (id),
  actor_api_key_id uuid references public.logbook_api_keys (id),
  actor_role text,
  before_fields jsonb,
  after_fields jsonb,
  detail text,
  created_at timestamptz not null default now(),
  check (actor_user_id is not null or actor_api_key_id is not null)
);
create index if not exists logbook_row_events_row on public.logbook_row_events (business_id, row_id, id);

alter table public.logbook_api_keys enable row level security;
alter table public.logbook_api_key_usage enable row level security;
alter table public.logbook_batches enable row level security;
alter table public.logbook_pages enable row level security;
alter table public.logbook_rows enable row level security;
alter table public.logbook_row_events enable row level security;
revoke all on table public.logbook_api_keys, public.logbook_api_key_usage, public.logbook_batches,
  public.logbook_pages, public.logbook_rows, public.logbook_row_events from public, anon, authenticated;
grant select, insert, update, delete on table public.logbook_api_keys, public.logbook_api_key_usage, public.logbook_batches,
  public.logbook_pages, public.logbook_rows, public.logbook_row_events to service_role;

-- Queue extracted or imported rows as PENDING, in one transaction.
--   p_pages: [{ page_number, filename, media_type, byte_size, sha256, image_base64, page_note }]
--   p_rows:  [{ page_index (into p_pages) | null, row_index, fields, issues, row_hash }]
-- A row whose hash already exists (pending or approved) in the business is
-- skipped, so sending the same rows again adds nothing.
create or replace function public.logbook_queue(
  p_business_id uuid,
  p_source text,
  p_model text,
  p_reference text,
  p_user_id uuid,
  p_role text,
  p_api_key_id uuid,
  p_batch_id uuid,
  p_pages jsonb,
  p_rows jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch_id uuid := p_batch_id;
  v_new_batch boolean := false;
  v_page jsonb;
  v_row jsonb;
  v_page_ids uuid[] := '{}';
  v_page_id uuid;
  v_row_id uuid;
  v_existing public.logbook_rows;
  v_inserted jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_base integer;
begin
  if v_batch_id is not null then
    perform 1 from public.logbook_batches
      where id = v_batch_id and business_id = p_business_id and source = p_source;
    if not found then
      return jsonb_build_object('status', 'batch_not_found');
    end if;
  else
    insert into public.logbook_batches (business_id, source, model, reference, created_by, api_key_id)
    values (p_business_id, p_source, p_model, p_reference, p_user_id, p_api_key_id)
    returning id into v_batch_id;
    v_new_batch := true;
  end if;

  select coalesce(max(page_number), 0) into v_base from public.logbook_pages where batch_id = v_batch_id;
  for v_page in select * from jsonb_array_elements(coalesce(p_pages, '[]'::jsonb)) loop
    v_base := v_base + 1;
    insert into public.logbook_pages (business_id, batch_id, page_number, filename, media_type, byte_size, sha256, image_base64, page_note)
    values (p_business_id, v_batch_id, v_base, v_page->>'filename', v_page->>'media_type', (v_page->>'byte_size')::integer,
            v_page->>'sha256', v_page->>'image_base64', v_page->>'page_note')
    returning id into v_page_id;
    v_page_ids := v_page_ids || v_page_id;
  end loop;

  select coalesce(max(row_index), 0) into v_base from public.logbook_rows where batch_id = v_batch_id;
  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    v_page_id := case when v_row->>'page_index' is null then null else v_page_ids[(v_row->>'page_index')::integer + 1] end;
    v_row_id := null;
    insert into public.logbook_rows (business_id, batch_id, page_id, row_index, fields, issues, row_hash)
    values (p_business_id, v_batch_id, v_page_id, v_base + 1, v_row->'fields', coalesce(v_row->'issues', '[]'::jsonb), v_row->>'row_hash')
    on conflict (business_id, row_hash) where status <> 'rejected' do nothing
    returning id into v_row_id;
    if v_row_id is null then
      select * into v_existing from public.logbook_rows
        where business_id = p_business_id and row_hash = v_row->>'row_hash' and status <> 'rejected';
      v_skipped := v_skipped || jsonb_build_object(
        'rowIndex', (v_row->>'row_index')::integer, 'existingRowId', v_existing.id,
        'existingBatchId', v_existing.batch_id, 'existingStatus', v_existing.status);
    else
      v_base := v_base + 1;
      v_inserted := v_inserted || to_jsonb(v_row_id);
      insert into public.logbook_row_events (business_id, batch_id, row_id, action, actor_user_id, actor_api_key_id, actor_role, after_fields)
      values (p_business_id, v_batch_id, v_row_id, case when p_source = 'api' then 'imported' else 'extracted' end,
              p_user_id, p_api_key_id, p_role, v_row->'fields');
    end if;
  end loop;

  -- An import that added nothing leaves no empty batch behind.
  if v_new_batch and jsonb_array_length(v_inserted) = 0 and coalesce(array_length(v_page_ids, 1), 0) = 0 then
    delete from public.logbook_batches where id = v_batch_id;
    v_batch_id := null;
  end if;

  return jsonb_build_object('status', 'queued', 'batchId', v_batch_id, 'pageIds', to_jsonb(v_page_ids),
                            'insertedRowIds', v_inserted, 'skipped', v_skipped);
end;
$$;

-- Admin edit of a PENDING row (fields, issues and hash recomputed by the server).
create or replace function public.logbook_edit_row(
  p_business_id uuid,
  p_row_id uuid,
  p_user_id uuid,
  p_role text,
  p_fields jsonb,
  p_issues jsonb,
  p_row_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.logbook_rows;
begin
  select * into v_row from public.logbook_rows where id = p_row_id and business_id = p_business_id for update;
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  if v_row.status <> 'pending' then return jsonb_build_object('status', 'not_pending', 'rowStatus', v_row.status); end if;
  begin
    update public.logbook_rows
      set fields = p_fields, issues = p_issues, row_hash = p_row_hash, edited_by = p_user_id, edited_at = clock_timestamp()
      where id = p_row_id;
  exception when unique_violation then
    return jsonb_build_object('status', 'duplicate');
  end;
  insert into public.logbook_row_events (business_id, batch_id, row_id, action, actor_user_id, actor_role, before_fields, after_fields)
  values (p_business_id, v_row.batch_id, p_row_id, 'edited', p_user_id, p_role, v_row.fields, p_fields);
  return jsonb_build_object('status', 'edited');
end;
$$;

-- Reject keeps the row and its history; nothing is written to live data.
create or replace function public.logbook_reject_row(
  p_business_id uuid,
  p_row_id uuid,
  p_user_id uuid,
  p_role text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.logbook_rows;
begin
  select * into v_row from public.logbook_rows where id = p_row_id and business_id = p_business_id for update;
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  if v_row.status <> 'pending' then return jsonb_build_object('status', 'not_pending', 'rowStatus', v_row.status); end if;
  update public.logbook_rows
    set status = 'rejected', reviewed_by = p_user_id, reviewed_at = clock_timestamp(), reject_reason = p_reason
    where id = p_row_id;
  insert into public.logbook_row_events (business_id, batch_id, row_id, action, actor_user_id, actor_role, before_fields, detail)
  values (p_business_id, v_row.batch_id, p_row_id, 'rejected', p_user_id, p_role, v_row.fields, p_reason);
  return jsonb_build_object('status', 'rejected');
end;
$$;

-- Approve: ONE transaction that (1) locks the pending row and checks it is still
-- the content the server validated, (2) compare-and-swaps the business snapshot
-- (the live records), (3) marks the row approved and (4) writes the audit event.
-- Any failed check changes nothing.
create or replace function public.commit_logbook_approval(
  p_business_id uuid,
  p_row_id uuid,
  p_expected_row_hash text,
  p_expected_updated_at timestamptz,
  p_snapshot jsonb,
  p_user_id uuid,
  p_role text,
  p_live_record_ids jsonb,
  p_issues jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row public.logbook_rows;
  v_version timestamptz := clock_timestamp();
  v_rows integer;
begin
  select * into v_row from public.logbook_rows where id = p_row_id and business_id = p_business_id for update;
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  if v_row.status <> 'pending' then return jsonb_build_object('status', 'not_pending', 'rowStatus', v_row.status); end if;
  if v_row.row_hash <> p_expected_row_hash then return jsonb_build_object('status', 'row_changed'); end if;

  update public.workspace_snapshots
    set snapshot = p_snapshot, updated_at = v_version, updated_by = p_user_id
    where business_id = p_business_id and updated_at = p_expected_updated_at;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then return jsonb_build_object('status', 'conflict'); end if;

  update public.logbook_rows
    set status = 'approved', reviewed_by = p_user_id, reviewed_at = v_version, live_record_ids = p_live_record_ids, issues = p_issues
    where id = p_row_id;
  insert into public.logbook_row_events (business_id, batch_id, row_id, action, actor_user_id, actor_role, after_fields, detail)
  values (p_business_id, v_row.batch_id, p_row_id, 'approved', p_user_id, p_role, v_row.fields, p_live_record_ids::text);
  return jsonb_build_object('status', 'approved', 'version', v_version);
end;
$$;

-- Fixed-window rate limit for one automation key. Returns true when the request
-- is within the limit; also stamps last_used_at.
create or replace function public.logbook_rate_take(p_key_id uuid, p_limit integer, p_window_seconds integer)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_window timestamptz := to_timestamp(floor(extract(epoch from clock_timestamp()) / p_window_seconds) * p_window_seconds);
  v_count integer;
begin
  delete from public.logbook_api_key_usage where key_id = p_key_id and window_start < v_window - interval '1 day';
  insert into public.logbook_api_key_usage (key_id, window_start, request_count)
  values (p_key_id, v_window, 1)
  on conflict (key_id, window_start) do update set request_count = public.logbook_api_key_usage.request_count + 1
  returning request_count into v_count;
  update public.logbook_api_keys set last_used_at = clock_timestamp() where id = p_key_id;
  return v_count <= p_limit;
end;
$$;

revoke all on function public.logbook_queue(uuid, text, text, text, uuid, text, uuid, uuid, jsonb, jsonb) from public, anon, authenticated;
revoke all on function public.logbook_edit_row(uuid, uuid, uuid, text, jsonb, jsonb, text) from public, anon, authenticated;
revoke all on function public.logbook_reject_row(uuid, uuid, uuid, text, text) from public, anon, authenticated;
revoke all on function public.commit_logbook_approval(uuid, uuid, text, timestamptz, jsonb, uuid, text, jsonb, jsonb) from public, anon, authenticated;
revoke all on function public.logbook_rate_take(uuid, integer, integer) from public, anon, authenticated;
grant execute on function public.logbook_queue(uuid, text, text, text, uuid, text, uuid, uuid, jsonb, jsonb) to service_role;
grant execute on function public.logbook_edit_row(uuid, uuid, uuid, text, jsonb, jsonb, text) to service_role;
grant execute on function public.logbook_reject_row(uuid, uuid, uuid, text, text) to service_role;
grant execute on function public.commit_logbook_approval(uuid, uuid, text, timestamptz, jsonb, uuid, text, jsonb, jsonb) to service_role;
grant execute on function public.logbook_rate_take(uuid, integer, integer) to service_role;


commit;
